import React from "react";
import { Link } from "react-router-dom";
import "../styles/Header.css"; // import header style file

const Header = () => {
  return (
    <header className="header">
      {/* Left: Brand Logo */}
      <div className="header-logo">
        <span className="logo-main">UTAS</span>
        <span className="logo-accent">Link</span>
      </div>

      {/* Right: Navigation Menu */}
      <nav className="header-nav">
        <Link to="/" className="nav-item">
          Home
        </Link>
        <Link to="/find" className="nav-item">
          Find Job
        </Link>
        <Link to="/StudentLogin" className="nav-item">
          Login
        </Link>
        <Link to="/StudentRegister" className="nav-item register-btn">
          Register
        </Link>
      </nav>
    </header>
  );
};

export default Header;
